(() => {
  // GPS do aparelho emulado (T7). O Chromium headless trava `getCurrentPosition({maximumAge: 0})` quando já existe um
  // `watchPosition` ativo — e o app do técnico faz exatamente isso (rastreia a cada 30 s e pede a posição no check-in).
  // Este stub devolve a posição atual na hora, para as duas chamadas, e `__setGeo` "anda" com o aparelho e avisa quem observa.
  if (window.__geoStub) return 'ja-instalado';
  const st = { lat: -22.9035, lng: -43.1038, acc: 12 };
  const pos = () => ({
    coords: { latitude: st.lat, longitude: st.lng, accuracy: st.acc, altitude: null, altitudeAccuracy: null, heading: null, speed: null },
    timestamp: Date.now(),
  });
  const watchers = new Map();
  let seq = 0;
  const g = navigator.geolocation;
  g.getCurrentPosition = (ok) => { setTimeout(() => ok(pos()), 60); };
  g.watchPosition = (ok) => { const id = ++seq; watchers.set(id, ok); setTimeout(() => { if (watchers.has(id)) ok(pos()); }, 90); return id; };
  g.clearWatch = (id) => { watchers.delete(id); };
  window.__setGeo = (lat, lng, acc) => { st.lat = lat; st.lng = lng; if (acc) st.acc = acc; watchers.forEach((cb) => cb(pos())); return [st.lat, st.lng]; };
  window.__geoStub = true;
  return 'instalado';
})()
